<?php
require_once __DIR__ . '/app.php'; require_login(); $me = current_user();
if ($_SERVER['REQUEST_METHOD'] === 'POST' && ($_POST['action'] ?? '') === 'create_post') {
    verify_csrf();
    try { $path = upload_image('photo'); if (!$path) throw new RuntimeException('Choose an image to share.'); $caption = trim((string)($_POST['caption'] ?? '')); if (mb_strlen($caption) > 2000) throw new RuntimeException('Captions must be 2,000 characters or fewer.'); $stmt = $conn->prepare('INSERT INTO posts (user_id, image_path, caption) VALUES (?, ?, ?)'); $stmt->bind_param('iss', $me['id'], $path, $caption); $stmt->execute(); flash('Your post is live.'); }
    catch (Throwable $e) { flash($e instanceof RuntimeException ? $e->getMessage() : 'Could not publish your post.', 'error'); }
    redirect('feed.php');
}
$stmt = $conn->prepare('SELECT p.id, p.image_path, p.caption, p.created_at, u.id AS author_id, u.username, u.display_name, u.avatar_path, (SELECT COUNT(*) FROM likes l WHERE l.post_id=p.id) AS like_count, (SELECT COUNT(*) FROM comments c WHERE c.post_id=p.id) AS comment_count, EXISTS(SELECT 1 FROM likes l2 WHERE l2.post_id=p.id AND l2.user_id=?) AS liked FROM posts p JOIN users u ON u.id=p.user_id WHERE p.user_id=? OR p.user_id IN (SELECT f.followed_id FROM follows f WHERE f.follower_id=?) ORDER BY p.created_at DESC LIMIT 60'); $stmt->bind_param('iii', $me['id'], $me['id'], $me['id']); $stmt->execute(); $posts = $stmt->get_result();
page_start('Your feed', 'feed');
?>
<main class="app-layout"><aside class="side-panel"><div class="welcome-card"><span class="eyebrow">YOUR SPACE</span><h2>Good to see you, <?= e($me['display_name']) ?>.</h2><p>Your feed is a collection of people and ideas you chose to keep close.</p><a class="text-link" href="explore.php">Find people to follow <span>→</span></a></div><div class="side-note"><span class="side-note-icon">✦</span><div><strong>Make it yours</strong><p>Share a moment, celebrate a win, or start a conversation.</p></div></div></aside><section class="feed-column"><div class="section-heading"><div><span class="eyebrow muted">THE LATEST</span><h1>Your feed<span class="heading-dot">.</span></h1></div><a class="subtle-link" href="explore.php">Explore people ↗</a></div><form class="composer card" method="post" enctype="multipart/form-data"><input type="hidden" name="csrf" value="<?= e(csrf_token()) ?>"><input type="hidden" name="action" value="create_post"><img class="avatar" src="<?= e(avatar($me)) ?>" alt="Your avatar"><div class="composer-fields"><textarea name="caption" rows="2" maxlength="2000" placeholder="What’s on your mind, <?= e($me['display_name']) ?>?"></textarea><div class="composer-bottom"><label class="file-label">＋ Add a photo <input type="file" name="photo" accept="image/jpeg,image/png,image/webp,image/gif" required></label><button class="btn primary" type="submit">Share post <span>→</span></button></div></div></form>
<?php if ($posts->num_rows === 0): ?><div class="empty-state card"><div class="empty-icon">✦</div><h2>Your feed starts here.</h2><p>Follow a few people or publish your first post to bring this space to life.</p><a class="btn primary" href="explore.php">Explore the community <span>→</span></a></div><?php endif; ?>
<?php while ($post = $posts->fetch_assoc()): ?><article class="post-card card"><div class="post-header"><a class="author" href="profile.php?u=<?= urlencode($post['username']) ?>"><img class="avatar" src="<?= e(avatar(['avatar_path'=>$post['avatar_path']])) ?>" alt=""><span><strong><?= e($post['display_name']) ?></strong><small>@<?= e($post['username']) ?></small></span></a><time><?= e(date('M j · g:i a', strtotime($post['created_at']))) ?></time></div><?php if ($post['caption'] !== ''): ?><p class="post-caption"><?= nl2br(e($post['caption'])) ?></p><?php endif; ?><a class="post-image-link" href="post.php?id=<?= (int)$post['id'] ?>"><img class="post-image" src="<?= e($post['image_path']) ?>" alt="Post by <?= e($post['username']) ?>" loading="lazy"></a><div class="post-actions"><form method="post" action="like.php"><input type="hidden" name="csrf" value="<?= e(csrf_token()) ?>"><input type="hidden" name="post_id" value="<?= (int)$post['id'] ?>"><button class="action-button <?= $post['liked'] ? 'liked' : '' ?>" type="submit"><?= $post['liked'] ? '♥ Liked' : '♡ Like' ?> <span><?= (int)$post['like_count'] ?></span></button></form><a class="action-button" href="post.php?id=<?= (int)$post['id'] ?>">◯ Comments <span><?= (int)$post['comment_count'] ?></span></a></div></article><?php endwhile; ?></section><aside class="right-panel"><div class="mini-card"><span class="eyebrow muted">A LITTLE REMINDER</span><p>Good things happen when you share what matters to you.</p><span class="mini-spark">✦</span></div><div class="footer-links"><a href="README.md">About this project</a><span>·</span><span>Social Pulse © <?= date('Y') ?></span></div></aside></main>
<?php page_end(); ?>
